// Umbral de autonomía: la decisión final es determinística (no la toma el LLM).
const UMBRAL_EXACTITUD = 4;   // exactitud_factual < 4  => se congela la autonomía
const UMBRAL_MINIMO = 3;      // cualquier otro criterio < 3 => revisión humana

const ev = $input.item.json.output || {};
const entrada = $('Recibir Respuesta a Evaluar').item.json;
const num = (v) => Number(v) || 0;
const scores = {
  exactitud_factual: num(ev.exactitud_factual),
  cobertura_consulta: num(ev.cobertura_consulta),
  tono_profesional: num(ev.tono_profesional),
  ausencia_alucinaciones: num(ev.ausencia_alucinaciones),
};
const puntaje_global = Math.round((Object.values(scores).reduce((a, b) => a + b, 0) / 4) * 100) / 100;

const motivos = [];
let decision = 'Aceptado';
if (!ev.veredicto || !scores.exactitud_factual) {
  decision = 'Corregir';
  motivos.push('el Juez no devolvió una evaluación válida');
} else {
  if (scores.exactitud_factual < UMBRAL_EXACTITUD) motivos.push(`exactitud_factual ${scores.exactitud_factual} < ${UMBRAL_EXACTITUD}`);
  for (const [k, v] of Object.entries(scores)) {
    if (k !== 'exactitud_factual' && v < UMBRAL_MINIMO) motivos.push(`${k} ${v} < ${UMBRAL_MINIMO}`);
  }
  if (ev.veredicto !== 'Aceptado') motivos.push(`veredicto del Juez: ${ev.veredicto}`);
  if (ev.veredicto === 'Rechazado' || scores.exactitud_factual <= 2 || scores.ausencia_alucinaciones <= 2) decision = 'Rechazado';
  else if (motivos.length) decision = 'Corregir';
}

return { json: {
  ...entrada,
  evaluacion: { ...scores, cita_fuente: !!ev.cita_fuente, puntaje_global, veredicto_juez: ev.veredicto || 'sin veredicto', razon: ev.razon || '' },
  decision,
  autonomia: decision === 'Aceptado' ? 'autonoma' : 'congelada (revisión humana)',
  motivos_umbral: motivos.join('; ') || 'supera todos los umbrales',
  umbrales: { exactitud_factual_minima: UMBRAL_EXACTITUD, resto_criterios_minimo: UMBRAL_MINIMO },
}};
